def IM(name, h=190): return FIG(name).replace('<img class="fig"', f'<img style="height: {h}px; border-radius: 12px; border: 3px solid #D5DEEA; vertical-align: middle; margin-inline-start: 24px"')
def SV(svg, h=300): return svg.replace('<svg class="svgfig', f'<svg style="height: {h}px; width: auto; vertical-align: middle" class="svgfig')
def K(t): return f'<b style="color: #C2410C">{t}</b>'
def TL(*t): return '<span style="display: inline-flex; gap: 56px; align-items: flex-end">' + ''.join(f'<span style="display: inline-flex; flex-direction: column; align-items: center; gap: 6px">{f}<span style="font-size: 34px; color: #3B5480">{c}</span></span>' for f, c in t) + '</span>'
def A(deg, start=0, h=150, **k): return SV(ANG(deg, start, **k), h)
